/**
 * Sentry, set up for the "shared environment" pattern.
 *
 * The browser extension injects code into ATS web pages (Greenhouse, Lever,
 * Workday, etc.), and those pages may themselves run Sentry. Calling the
 * global `Sentry.init()` would pollute that shared global state and can
 * cause events to leak between projects.
 *
 * Instead, every extension execution context (content script, service
 * worker, extension iframe) builds its own `BrowserClient` and `Scope` and
 * uses scope-bound capture calls. See:
 * https://docs.sentry.io/platforms/javascript/best-practices/browser-extensions/
 *
 * Call sites use the named wrappers exported below (`captureException`,
 * `captureMessage`, `setUser`) — never `Sentry.captureException(...)` from
 * `@sentry/browser` directly, which would target the global scope.
 */

import {
  BrowserClient,
  defaultStackParser,
  type ErrorEvent,
  getDefaultIntegrations,
  makeFetchTransport,
  Scope,
  type SeverityLevel,
  type User,
} from "@sentry/browser";

import { getCurrentUser } from "./storage";

const DSN =
  "https://8bb8feac65714515a168bd8317e8277c@o316967.ingest.sentry.io/5809108";

const IGNORED_ERRORS = ["Failed to fetch", "Extension context invalidated"];

// Default integrations that touch global state and would conflict with a
// host page's own Sentry SDK. Per Sentry's shared-environment docs.
const GLOBAL_STATE_INTEGRATIONS = new Set([
  "BrowserApiErrors",
  "BrowserSession",
  "Breadcrumbs",
  "ConversationId",
  "GlobalHandlers",
  "FunctionToString",
]);

// Module-local scope. Populated by initSentry(); when null, the wrapper
// functions are silent no-ops (matches the pre-v10 behavior outside
// production/beta where Sentry.init() never ran).
let scope: Scope | null = null;

export const initSentry = (): void => {
  if (
    process.env.APP_ENV != null &&
    !["production", "beta"].includes(process.env.APP_ENV)
  ) {
    return;
  }

  if (scope != null) return; // idempotent — each entry point calls initSentry()

  const integrations = getDefaultIntegrations({}).filter(
    (integration) => !GLOBAL_STATE_INTEGRATIONS.has(integration.name),
  );

  const client = new BrowserClient({
    dsn: DSN,
    environment: process.env.SENTRY_ENV,
    // Set by the release workflow to match the `sentry-cli releases new`
    // version tag (e.g. "vX.Y.Z"). Required so Sentry can match captured
    // events against the sourcemaps uploaded for that release.
    release: process.env.SENTRY_RELEASE ?? undefined,
    sendDefaultPii: true,
    transport: makeFetchTransport,
    stackParser: defaultStackParser,
    integrations,
    beforeSend(event: ErrorEvent) {
      // Strip absolute paths from stack frames so issues group cleanly.
      event.exception?.values?.[0]?.stacktrace?.frames?.forEach((frame) => {
        if (frame.filename != null) {
          frame.filename = frame.filename.substring(
            frame.filename.lastIndexOf("/"),
          );
        }
      });
      return event;
    },
  });

  scope = new Scope();
  scope.setClient(client);
  client.init();

  getCurrentUser().then((currentUser) => {
    if (currentUser == null) return;
    setUser({
      id: currentUser.id,
      username: currentUser.email,
    });
  });
};

type CaptureContext = {
  level?: SeverityLevel;
  tags?: Record<string, string>;
  extra?: Record<string, unknown>;
};

const isIgnored = (message: string): boolean =>
  IGNORED_ERRORS.some((ignored) => message.includes(ignored));

const applyContext = (s: Scope, context?: CaptureContext): Scope => {
  if (context?.tags != null) s.setTags(context.tags);
  if (context?.extra != null) s.setExtras(context.extra);
  if (context?.level != null) s.setLevel(context.level);
  return s;
};

export const captureException = (
  err: unknown,
  context?: CaptureContext,
): void => {
  if (scope == null) return;
  if (err instanceof Error && isIgnored(err.message)) return;
  applyContext(scope.clone(), context).captureException(err);
};

export const captureMessage = (
  message: string,
  context?: CaptureContext,
): void => {
  if (scope == null) return;
  if (isIgnored(message)) return;
  applyContext(scope.clone(), context).captureMessage(message, context?.level);
};

export const setUser = (user: User | null): void => {
  if (scope == null) return;
  scope.setUser(user);
};
