/**
 * Embeds a modal on the page that will show / hide an iframe in
 * response to the `showModal` / `hideModal` extension events.
 *
 * This script should be site-agnostic, and site-specific logic
 * should be contained in another content script (like
 * `greenhouseJdContentScript`, for example)
 */
import { disableBodyScroll, enableBodyScroll } from "body-scroll-lock";

import { addPassiveMessageListener, getTabId } from "./message";
import { captureException } from "./sentry";
import { buildUrl } from "./url";

let modalShowing = false;

/**
 * We need an iframe whose `src` is listed in the manifest's
 * `web_accessible_resources` in order to then load whatever iframe
 * we wish. Otherwise, BrightHire (or localhost) URLs get blocked
 * by the host site (e.g. Greenhouse, Lever, etc.) content security policy.
 *
 * See: https://stackoverflow.com/questions/24641592
 */
const modal = document.createElement("iframe");
modal.allow = "clipboard-write";
const modalUrl = chrome.runtime.getURL("modal.html");
modal.style.cssText = `
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 2147483647;
  visibility: hidden;
  border: none;
`;

type InitModalParams = {
  path?: string;
  /** Additional URL params to add to the app URL passed to the iframe */
  urlParams?: Record<string, string>;
};

const onMessage: MessageListener = ({ message }) => {
  try {
    if (message.action === "showModal") {
      showModal();
    } else if (message.action === "hideModal") {
      hideModal();
    }
  } catch (err) {
    captureException(err);
    throw err;
  }
};

let listenerInitialized = false;
const initListeners = (): void => {
  if (!listenerInitialized) {
    listenerInitialized = true;
    addPassiveMessageListener(onMessage);
  }
};

/**
 * Begins iframe loading by setting it's `src`. This should be called
 * before `showModal`
 */
export const initModal = async ({
  path = "/extension",
  urlParams,
}: InitModalParams = {}): Promise<void> => {
  const tabUrl = window.location.href;
  const tabId = await getTabId();
  if (!tabId) return;

  initListeners();

  const appUrl = await buildUrl(path, {
    tabId: tabId.toString(),
    tabUrl,
    ...urlParams,
  });

  const modalSrc = await buildUrl(modalUrl, {
    appUrl: encodeURIComponent(appUrl.href),
  });

  if (modal.src !== modalSrc.href) {
    modal.src = modalSrc.href;
  }

  if (!document.body.contains(modal)) {
    document.body.appendChild(modal);
  }
};

export const hideModal = (): void => {
  if (!modalShowing) return;
  modalShowing = false;
  modal.style.visibility = "hidden";
  enableBodyScroll(modal);
};

/** This needs to be called after `setModalSrc`  */
export const showModal = (): void => {
  if (modalShowing) return;
  modalShowing = true;
  modal.style.visibility = "visible";
  disableBodyScroll(modal);
};
