/**
 * Bridges the drawer iframe and the Custom Template Studio modal iframe.
 *
 * Lifecycle:
 *  1. The drawer iframe sends a `showCustomTemplateStudio` message
 *     (via service worker → `chrome.tabs.sendMessage`).
 *  2. This content script lazily initializes the modal iframe with the
 *     studio's URL — `/extension/template-studio` on the main app — passing
 *     `callId`, `mode` and (optionally) `customTemplateId` as URL params,
 *     then makes it visible.
 *  3. When the user saves inside the modal, the studio React app calls
 *     `hideModal(tabId, { customTemplate })` for custom templates or
 *     `hideModal(tabId, { format, customTemplateId })` for built-in formats.
 *     The generic `modal.ts` handler hides the iframe; this script forwards
 *     the applied format/template back to the drawer iframe.
 *
 * The "lazy" init is intentional: unlike the JD / questions import flows that
 * preload the modal iframe at page load, this modal is only useful when the
 * user explicitly clicks "Create / Edit template" inside the drawer, so we
 * pay the React-bundle cost only on first open.
 */
import { addMessageListener, sendMessage } from "../../utils/message";
import { initModal, showModal } from "../../utils/modal";
import { captureException, initSentry } from "../../utils/sentry";

initSentry();

let initialized = false;

const openStudio = async (payload: Message["payload"]): Promise<void> => {
  const callId = payload?.callId;
  if (!callId) {
    throw new Error(
      "showCustomTemplateStudio received without callId; cannot open studio",
    );
  }

  const urlParams: Record<string, string> = {
    callId,
    mode: payload?.customTemplateStudioMode ?? "create",
  };
  const customTemplateId = payload?.customTemplateId;
  if (customTemplateId) {
    urlParams.customTemplateId = customTemplateId;
  }

  // initModal is idempotent — it only resets `src` if the URL changed, so
  // re-opening with the same callId / mode is essentially instant.
  await initModal({
    path: "/extension/template-studio",
    urlParams,
  });
  initialized = true;
  showModal();
};

const onMessage: MessageListener = ({ message }) => {
  try {
    if (message.action === "showCustomTemplateStudio") {
      openStudio(message.payload).catch((err) => {
        captureException(err);
      });
      return;
    }

    // After the studio app calls `hideModal`, the generic modal.ts handler
    // hides the iframe. Forward the saved/applied selection back to the drawer
    // iframe so it can refresh its template list and switch the active format.
    if (
      message.action === "hideModal" &&
      initialized &&
      message.payload?.customTemplate
    ) {
      sendMessage({
        action: "customTemplateSaved",
        payload: {
          tabId: message.payload.tabId,
          customTemplate: message.payload.customTemplate,
        },
      });
      return;
    }

    if (
      message.action === "hideModal" &&
      initialized &&
      message.payload?.format
    ) {
      sendMessage({
        action: "customTemplateApplied",
        payload: {
          tabId: message.payload.tabId,
          format: message.payload.format,
          customTemplateId: message.payload.customTemplateId ?? null,
        },
      });
    }
  } catch (err) {
    captureException(err);
    throw err;
  }
};

addMessageListener(onMessage);
